args.command:
cd ~/captures; cat > /tmp/blob.py <<'EOF'
import sys
from PIL import Image
def blobs(f, cond):
    im=Image.open(f).convert('RGB'); w,h=im.size; px=im.load()
    seen=set(); out=[]
    for y in range(h):
        for x in range(w):
            if (x,y) in seen or not cond(px[x,y]): continue
            st=[(x,y)]; seen.add((x,y)); pts=[]
            while st:
                a,b=st.pop(); pts.append((a,b))
                for c,d in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                    if 0<=c<w and 0<=d<h and (c,d) not in seen and cond(px[c,d]):
                        seen.add((c,d)); st.append((c,d))
            if len(pts)>30: out.append((round(sum(p[0] for p in pts)/len(pts),2),round(sum(p[1] for p in pts)/len(pts),2),len(pts)))
    return out
mode=sys.argv[1]
cond = (lambda p: min(p)>215 and abs(p[0]-p[2])<20) if mode=='white' else (lambda p: max(p)<60)
for f in sys.argv[2:]:
    b=blobs(f,cond)
    print(f, [x for x in b if x[2]<20000])
EOF
python3 /tmp/blob.py white wrist_007.png wrist_009.png wrist_010.png wrist_011.png; python3 /tmp/blob.py dark wrist_006.png wrist_008.png

